<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/database/setup.php';initializeRESposDatabase();require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$db=getDBConnection();$s=$db->prepare('SELECT * FROM usuarios WHERE username=? AND activo=1');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['usuario']=['id'=>$u['id'],'username'=>$u['username'],'nombre'=>$u['nombre'],'rol'=>$u['rol']];logAction('LOGIN','Inicio de sesión');header('Location: '.url('index.php'));exit;}$error='Usuario o contraseña incorrectos.';}$config=getAppConfig();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RESpos · Acceso</title><link rel="stylesheet" href="<?=url('assets/css/style.css')?>"></head><body><div class="login"><div class="card login-box"><img class="login-logo" src="<?=publicAsset($config['logo_path']??null)?>"><h1 class="gold" style="text-align:center">RESpos</h1><p class="muted" style="text-align:center">Gestión integral del restaurante</p><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif;?><form method="post"><label>Usuario</label><input name="username" autocomplete="username" required><label>Contraseña</label><input type="password" name="password" autocomplete="current-password" required><button class="btn gold" style="width:100%;margin-top:15px">Entrar</button></form><p class="muted" style="font-size:.8rem;text-align:center;margin-bottom:0">Primer acceso: admin / admin123 · Cambia la contraseña desde Usuarios.</p></div></div></body></html>
